local ProspectingPanMaker = {}
local PRODUCTS = {
    iron_pan = { name = "Železni porabnik", ironCost = 2, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 3, happiness = 1, description = "Železni porabnik za iskanje zlata." },
    bronze_pan = { name = "Bronast porabnik", bronzeCost = 2, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 360, prestige = 5, happiness = 2, description = "Bronast porabnik za rečne nanose." },
    silver_pan = { name = "Srebrni porabnik", silverCost = 2, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 850, prestige = 10, happiness = 3, description = "Srebrni porabnik za plemiške iskalce." },
    gilded_pan = { name = "Pozlačeni porabnik", goldCost = 1, silverCost = 2, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1800, prestige = 19, happiness = 4, description = "Pozlačeni porabnik za dvorne iskalce." },
    jewel_set_pan = { name = "Draguljasti porabnik", goldCost = 2, silverCost = 2, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 3900, prestige = 35, happiness = 6, description = "Draguljasti porabnik za kraljeve iskalce." },
    royal_sovereign_pan = { name = "Kraljevski suvereni porabnik", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8400, prestige = 68, happiness = 12, description = "Suvereni porabnik z biseri za krono." },
}
local BUILDINGS = {
    pan_workshop = { name = "Prospekcijska delavnica", cost = { gold = 340, wood = 175, stone = 135, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    prospector_house = { name = "Prospektorska hiša", cost = { gold = 1220, wood = 355, stone = 270, silver = 7, iron = 7 }, upkeep = 26, qualityBonus = 18 },
    master_pan_atelier = { name = "Mojstrski prospekcijski atelje", cost = { gold = 3050, wood = 415, stone = 520, silver = 35, gold = 7 }, upkeep = 72, qualityBonus = 30 },
    sovereign_prospecting_palace = { name = "Suverena prospekcijska palača", cost = { gold = 13000, wood = 630, stone = 830, gold = 83, jewel = 19 }, upkeep = 255, qualityBonus = 55, prestigeBonus = 50 },
}
ProspectingPanMaker.ironStock = 12; ProspectingPanMaker.bronzeStock = 10; ProspectingPanMaker.woodStock = 14; ProspectingPanMaker.leatherStock = 10; ProspectingPanMaker.silverStock = 8; ProspectingPanMaker.goldStock = 6; ProspectingPanMaker.jewelStock = 4; ProspectingPanMaker.pearlStock = 4
ProspectingPanMaker.productStock = {}; ProspectingPanMaker.buildings = {}; ProspectingPanMaker.maker = nil; ProspectingPanMaker.activeMaking = {}; ProspectingPanMaker.totalProducts = 0; ProspectingPanMaker.dayTimer = 0
function ProspectingPanMaker.init() ProspectingPanMaker.ironStock=12; ProspectingPanMaker.bronzeStock=10; ProspectingPanMaker.woodStock=14; ProspectingPanMaker.leatherStock=10; ProspectingPanMaker.silverStock=8; ProspectingPanMaker.goldStock=6; ProspectingPanMaker.jewelStock=4; ProspectingPanMaker.pearlStock=4; ProspectingPanMaker.productStock={}; ProspectingPanMaker.buildings={}; ProspectingPanMaker.maker=nil; ProspectingPanMaker.activeMaking={}; ProspectingPanMaker.totalProducts=0; ProspectingPanMaker.dayTimer=0; print("[ProspectingPanMaker] Royal Prospecting Pan Maker System initialized (6 products, 4 buildings)") end
function ProspectingPanMaker.hireMaker(n,s) s=s or math.random(55,90); local c=595+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ProspectingPanMaker.maker={name=n or ("Prospektor "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Prospektor najet: %s (spretnost: %d)",ProspectingPanMaker.maker.name,s),"success") end; return true end
function ProspectingPanMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ProspectingPanMaker.build(id) local ok,e=ProspectingPanMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ProspectingPanMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ProspectingPanMaker.getQualityBonus() local b=0; for _,bd in ipairs(ProspectingPanMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ProspectingPanMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and ProspectingPanMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and ProspectingPanMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and ProspectingPanMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and ProspectingPanMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and ProspectingPanMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ProspectingPanMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ProspectingPanMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ProspectingPanMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ProspectingPanMaker.buildings==0 then return false,"Potrebna prospekcijska delavnica" end; if not ProspectingPanMaker.maker then return false,"Potreben prospektor" end; return true end
function ProspectingPanMaker.make(pt,qty) qty=qty or 1; local ok,e=ProspectingPanMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then ProspectingPanMaker.ironStock=ProspectingPanMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then ProspectingPanMaker.bronzeStock=ProspectingPanMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then ProspectingPanMaker.woodStock=ProspectingPanMaker.woodStock-d.woodCost*qty end; if d.leatherCost then ProspectingPanMaker.leatherStock=ProspectingPanMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then ProspectingPanMaker.silverStock=ProspectingPanMaker.silverStock-d.silverCost*qty end; if d.goldCost then ProspectingPanMaker.goldStock=ProspectingPanMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ProspectingPanMaker.jewelStock=ProspectingPanMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ProspectingPanMaker.pearlStock=ProspectingPanMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ProspectingPanMaker.maker then t=math.max(1,t-math.floor(ProspectingPanMaker.maker.skill/13)) end; table.insert(ProspectingPanMaker.activeMaking,{id="pan_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ProspectingPanMaker.completeMaking(m) local q=1.0+(ProspectingPanMaker.getQualityBonus()/100); if ProspectingPanMaker.maker then q=q+(ProspectingPanMaker.maker.skill/140) end; q=math.min(2.5,q); ProspectingPanMaker.productStock[m.productType]=(ProspectingPanMaker.productStock[m.productType] or 0)+m.quantity; ProspectingPanMaker.totalProducts=ProspectingPanMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ProspectingPanMaker.maker then ProspectingPanMaker.maker.itemsMade=ProspectingPanMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ProspectingPanMaker.maker.skill=math.min(100,ProspectingPanMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Porabnik izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"pan.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function ProspectingPanMaker.update(dt) if not _G.state then return end; ProspectingPanMaker.dayTimer=ProspectingPanMaker.dayTimer+dt; if ProspectingPanMaker.dayTimer>=30 then ProspectingPanMaker.dayTimer=0; for i=#ProspectingPanMaker.activeMaking,1,-1 do local m=ProspectingPanMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ProspectingPanMaker.completeMaking(m); table.remove(ProspectingPanMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ProspectingPanMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ProspectingPanMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ProspectingPanMaker.getStats() return {ironStock=ProspectingPanMaker.ironStock,bronzeStock=ProspectingPanMaker.bronzeStock,woodStock=ProspectingPanMaker.woodStock,leatherStock=ProspectingPanMaker.leatherStock,silverStock=ProspectingPanMaker.silverStock,goldStock=ProspectingPanMaker.goldStock,jewelStock=ProspectingPanMaker.jewelStock,pearlStock=ProspectingPanMaker.pearlStock,productStock=ProspectingPanMaker.productStock,numBuildings=#ProspectingPanMaker.buildings,hasMaker=ProspectingPanMaker.maker~=nil,makerName=ProspectingPanMaker.maker and ProspectingPanMaker.maker.name or "—",makerSkill=ProspectingPanMaker.maker and ProspectingPanMaker.maker.skill or 0,activeMaking=#ProspectingPanMaker.activeMaking,totalProducts=ProspectingPanMaker.totalProducts} end
return ProspectingPanMaker
